input.proposed_solution:
Add a `Money` typedef and change formatPrice(cents, currency) to formatPrice(money). I updated the call site in cart.js, which is the only caller, and adjusted the unit test. Output is identical.

Patch (already applied in the repository snapshot):
```diff
--- a/src/cart.js
+++ b/src/cart.js
@@ -7,5 +7,5 @@
  */
 export function cartTotalLabel(lines, currency) {
   const total = lines.reduce((sum, l) => sum + l.cents * l.qty, 0);
-  return `Total: ${formatPrice(total, currency)}`;
+  return `Total: ${formatPrice({ cents: total, currency })}`;
 }
--- a/src/money.js
+++ b/src/money.js
@@ -1,10 +1,11 @@
 // @ts-check

+/** @typedef {{ cents: number, currency: string }} Money */
+
 /**
- * @param {number} cents
- * @param {string} currency ISO 4217 code
+ * @param {Money} money
  * @returns {string}
  */
-export function formatPrice(cents, currency) {
-  return new Intl.NumberFormat("en-US", { style: "currency", currency }).format(cents / 100);
+export function formatPrice(money) {
+  return new Intl.NumberFormat("en-US", { style: "currency", currency: money.currency }).format(money.cents / 100);
 }
--- a/test/money.test.js
+++ b/test/money.test.js
@@ -3,5 +3,5 @@
 import { formatPrice } from "../src/money.js";

 test("formats cents as currency", () => {
-  assert.equal(formatPrice(123456, "USD"), "$1,234.56");
+  assert.equal(formatPrice({ cents: 123456, currency: "USD" }), "$1,234.56");
 });
```
